sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.script:
(function() {

    data.cases = [];

    var gr = new GlideRecord('x_1558402_smart_0_support_case'); // your case table

    // ✅ CORE LOGIC: show cases for logged-in / impersonated user
    gr.addQuery('opened_to', gs.getUserID());

    gr.orderByDesc('sys_created_on'); // optional sorting
    gr.query();

    while (gr.next()) {

    data.cases.push({
    number: gr.getValue('number'),
    description: gr.getValue('description'),
    state: gr.getDisplayValue('state'),
    priority: gr.getDisplayValue('priority')
});

    }

})();
